{"name":"i915_driver_suspend_switcheroo","qualified_name":"workspace-linux.drivers.gpu.drm.i915.i915_driver.i915_driver_suspend_switcheroo","label":"Function","file_path":"/workspace/linux/drivers/gpu/drm/i915/i915_driver.c","start_line":1210,"end_line":1235,"source":"int i915_driver_suspend_switcheroo(struct drm_i915_private *i915,
				   pm_message_t state)
{
	struct pci_dev *pdev = to_pci_dev(i915->drm.dev);
	int error;

	if (drm_WARN_ON_ONCE(&i915->drm, state.event != PM_EVENT_SUSPEND &&
			     state.event != PM_EVENT_FREEZE))
		return -EINVAL;

	if (i915->drm.switch_power_state == DRM_SWITCH_POWER_OFF)
		return 0;

	error = i915_drm_suspend(&i915->drm);
	if (error)
		return error;

	error = i915_drm_suspend_late(&i915->drm, false);
	if (error)
		return error;

	pci_save_state(pdev);
	pci_set_power_state(pdev, PCI_D3hot);

	return 0;
}
