{"name":"i915_pm_prepare","qualified_name":"workspace-linux.drivers.gpu.drm.i915.i915_driver.i915_pm_prepare","label":"Function","file_path":"/workspace/linux/drivers/gpu/drm/i915/i915_driver.c","start_line":1377,"end_line":1390,"source":"static int i915_pm_prepare(struct device *kdev)
{
	struct drm_i915_private *i915 = kdev_to_i915(kdev);

	if (!i915) {
		dev_err(kdev, "DRM not initialized, aborting suspend.\n");
		return -ENODEV;
	}

	if (i915->drm.switch_power_state == DRM_SWITCH_POWER_OFF)
		return 0;

