{"name":"intel_display_driver_suspend","qualified_name":"workspace-linux.drivers.gpu.drm.i915.display.intel_display_driver.intel_display_driver_suspend","label":"Function","file_path":"/workspace/linux/drivers/gpu/drm/i915/display/intel_display_driver.c","start_line":684,"end_line":706,"source":"int intel_display_driver_suspend(struct intel_display *display)
{
	struct drm_atomic_state *state;
	int ret;

	if (!HAS_DISPLAY(display))
		return 0;

	state = drm_atomic_helper_suspend(display->drm);
	ret = PTR_ERR_OR_ZERO(state);
	if (ret)
		drm_err(display->drm, "Suspending crtc's failed with %i\n",
			ret);
	else
		display->restore.modeset_state = state;

	/* ensure all DPT VMAs have been unpinned for intel_dpt_suspend() */
	flush_workqueue(display->wq.cleanup);

	intel_dp_mst_suspend(display);

	return ret;
}
